def exact_head_probability(prob,target):
    dp=[0.0]*(target+1);dp[0]=1.0
    for chance in prob:
        for heads in range(target,-1,-1):dp[heads]=dp[heads]*(1-chance)+(dp[heads-1]*chance if heads else 0)
    return dp[target]

